using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;
namespace Synkoz {internal static class TagIndexR19 {
 static readonly Dictionary<string,string[]> index=new Dictionary<string,string[]>(StringComparer.OrdinalIgnoreCase);internal static Task Loading=Task.FromResult(0);internal static readonly List<string> Errors=new List<string>();
 internal static void Start(){var roots=new[]{AnimationPickerA01.PackFolder,FoldersR2.Get("animation")};Loading=Task.Run(()=>Load(roots));}
 internal static void Load(IEnumerable<string> roots){var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var root in roots)Scan(root,visited);}
 static void Scan(string folder,HashSet<string> visited){try{if(!Directory.Exists(folder)||(File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0||!visited.Add(Path.GetFullPath(folder)))return;var tags=FolderTagsR18.Read(folder);string common;tags.TryGetValue("communs",out common);foreach(var file in Directory.GetFiles(folder).Where(IsAnimation)){string own;if(!tags.TryGetValue(Path.GetFileName(file),out own)){string old=file+".tags.txt";own=File.Exists(old)?File.ReadAllText(old):"";}index[file]=Words((common??"")+" "+(own??""));}foreach(var dir in Directory.GetDirectories(folder).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase))if(!new[]{"Archive","Validation","Sources","Fonctions archivees"}.Contains(Path.GetFileName(dir),StringComparer.OrdinalIgnoreCase))Scan(dir,visited);}catch(Exception ex){Errors.Add(folder+": "+ex.Message);}}
 internal static bool IsAnimation(string path){return new[]{".png",".gif",".mp4"}.Contains(Path.GetExtension(path).ToLowerInvariant());}
 internal static string[] Words(string text){return text.ToLowerInvariant().Split(new[]{' ',',',';','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries).Distinct().ToArray();}
 internal static string[] Find(string root,string query){string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;var tags=Words(query);return index.Where(p=>p.Key.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&tags.All(t=>p.Value.Contains(t))).Select(p=>p.Key).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase).ToArray();}
 internal const string Prompt=" Fournir également un fichier tags.txt UTF-8 dans chaque dossier du pack. Écrire [communs] sur une ligne, puis les tags communs aux animations du dossier, séparés par des espaces ou des virgules. Pour les tags spécifiques, ajouter une section portant le nom exact du fichier, par exemple [bouche_normale.gif], suivie de ses tags. Exemple :\n[communs]\nbouche personnage dessin\n[bouche_normale.gif]\nnormal parler\nLes sous-dossiers ont chacun leur propre tags.txt. Les recherches exigent tous les tags saisis ; aucune équivalence automatique (féminin/masculin, synonymes) n’est appliquée. Les tags sont mis à jour au lancement du logiciel.";
}}
